import csv
from collections import defaultdict

# Read the raw data
with open('outputs/t02_eurostat_raw.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Get unique (city_id, year) combinations
city_year_pairs = set()
for row in rows:
    city_year_pairs.add((row['city_id'], int(row['year'])))

# Get unique indicator_ids (excluding the header row)
indicator_ids = sorted(set(row['indicator_id'] for row in rows))

print(f"Total rows: {len(rows)}")
print(f"Unique city-year pairs: {len(city_year_pairs)}")
print(f"Indicator IDs: {indicator_ids}")

# Build the matrix: dictionary keyed by (city_id, year) -> {indicator_id: value}
matrix = {}
for row in rows:
    key = (row['city_id'], int(row['year']))
    if key not in matrix:
        matrix[key] = {}
    indicator_id = row['indicator_id']
    if indicator_id in indicator_ids:
        matrix[key][indicator_id] = row['value']

# Build the output rows
output_rows = []
for (city_id, year) in city_year_pairs:
    row = {'city_id': city_id, 'city_name': '', 'year': str(year)}
    for ind_id in indicator_ids:
        if ind_id in matrix.get((city_id, year), {}):
            row[ind_id] = matrix[(city_id, year)][ind_id]
        else:
            row[ind_id] = ''
    output_rows.append(row)

# Sort by city_id, year
output_rows.sort(key=lambda r: (r['city_id'], int(r['year'])))

# Write the output CSV
with open('outputs/t11_city_indicator_matrix.csv', 'w', newline='', encoding='utf-8') as f:
    fieldnames = ['city_id', 'city_name', 'year'] + indicator_ids
    writer = csv.DictWriter(f, fieldnames=fieldnames, quoting=csv.QUOTE_MINIMAL)
    writer.writeheader()
    for row in output_rows:
        writer.writerow(row)

print("Done!")
EOF"}

